function fewestRolls(board: number[][]): number {
  const n = board.length, N = n * n;
  const jump = (c: number): number => {
    const q = Math.floor((c - 1) / n), row = n - 1 - q;
    let col = (c - 1) % n;
    if (q % 2 === 1) col = n - 1 - col;
    return board[row][col] === -1 ? c : board[row][col];
  };
  const best = new Array(N + 1).fill(Infinity);
  best[1] = 0;
  let changed = true;
  while (changed) {
    changed = false;
    for (let c = 1; c <= N; c++) {
      if (best[c] === Infinity) continue;
      for (let d = 1; d <= 6 && c + d <= N; d++) {
        const to = jump(c + d);
        if (best[c] + 1 < best[to]) { best[to] = best[c] + 1; changed = true; }
      }
    }
  }
  return best[N] === Infinity ? -1 : best[N];
}

