  };
  const dist = new Array(N + 1).fill(-1);
  dist[1] = 0;
  const queue = [1];
  for (let head = 0; head < queue.length; head++) {
    const c = queue[head];
    if (c === N) return dist[c];
    for (let d = 1; d <= 6 && c + d <= N; d++) {
      const to = jump(c + d);
      if (dist[to] === -1) { dist[to] = dist[c] + 1; queue.push(to); }
    }
  }
  return -1;
}

